import { ORDER_BADGES } from "./orderBadges";
import { PAYMENT_BADGES } from "./paymentBadges";
import { SHIPMENT_BADGES } from "./shipmentBadges";
import { Badge } from "./types";

export { Badge, Tone } from "./types";

/** Every status the back office can display. */
const ALL_BADGES: Readonly<Record<string, Badge>> = Object.freeze({
  ...ORDER_BADGES,
  ...SHIPMENT_BADGES,
  ...PAYMENT_BADGES,
});

const UNKNOWN_TONE = "neutral" as const;

export function badgeFor(status: string): Badge {
  const badge = ALL_BADGES[status];
  return badge ? { ...badge } : { label: status, tone: UNKNOWN_TONE };
}

export function knownStatuses(): string[] {
  return Object.keys(ALL_BADGES).sort();
}
import { OrderStatus } from "../../domain/order";
import { Badge } from "./types";

export const ORDER_BADGES: Record<OrderStatus, Badge> = {
  [OrderStatus.Pending]: { label: "접수 대기", tone: "warn" },
  [OrderStatus.Confirmed]: { label: "주문 확정", tone: "info" },
  [OrderStatus.Shipped]: { label: "출고", tone: "info" },
  [OrderStatus.Completed]: { label: "완료", tone: "success" },
  [OrderStatus.Cancelled]: { label: "취소", tone: "muted" },
};
import { PaymentStatus } from "../../domain/payment";
import { Badge } from "./types";

export const PAYMENT_BADGES: Record<PaymentStatus, Badge> = {
  [PaymentStatus.Pending]: { label: "결제 대기", tone: "neutral" },
  [PaymentStatus.Authorized]: { label: "승인", tone: "info" },
  [PaymentStatus.Captured]: { label: "결제 완료", tone: "success" },
  [PaymentStatus.Failed]: { label: "결제 실패", tone: "danger" },
  [PaymentStatus.Refunded]: { label: "환불", tone: "muted" },
};
import { ShipmentStatus } from "../../domain/shipment";
import { Badge } from "./types";

export const SHIPMENT_BADGES: Record<ShipmentStatus, Badge> = {
  [ShipmentStatus.Ready]: { label: "출고 준비", tone: "neutral" },
  [ShipmentStatus.InTransit]: { label: "배송 중", tone: "info" },
  [ShipmentStatus.Delivered]: { label: "배송 완료", tone: "success" },
  [ShipmentStatus.Failed]: { label: "배송 실패", tone: "danger" },
  [ShipmentStatus.Returned]: { label: "반송", tone: "warn" },
};
export type Tone = "neutral" | "info" | "success" | "warn" | "danger" | "muted";

export interface Badge {
  label: string;
  tone: Tone;
}
import { OrderStatus } from "../domain/order";
import { PaymentStatus } from "../domain/payment";
import { ShipmentStatus } from "../domain/shipment";

// Lower number = shown first in the back-office list.
export const ORDER_PRIORITY: Record<OrderStatus, number> = {
  [OrderStatus.Pending]: 0,
  [OrderStatus.Confirmed]: 1,
  [OrderStatus.Shipped]: 2,
  [OrderStatus.Completed]: 4,
  [OrderStatus.Cancelled]: 5,
};

export const PAYMENT_PRIORITY: Record<PaymentStatus, number> = {
  [PaymentStatus.Failed]: 0,
  [PaymentStatus.Pending]: 1,
  [PaymentStatus.Authorized]: 2,
  [PaymentStatus.Captured]: 3,
  [PaymentStatus.Refunded]: 4,
};

export const SHIPMENT_PRIORITY: Record<ShipmentStatus, number> = {
  [ShipmentStatus.Failed]: 0,
  [ShipmentStatus.Returned]: 1,
  [ShipmentStatus.Ready]: 2,
  [ShipmentStatus.InTransit]: 3,
  [ShipmentStatus.Delivered]: 4,
};

export function orderPriority(status: OrderStatus): number {
  return ORDER_PRIORITY[status] ?? 9;
}
import { OrderRow } from "./orderRowPresenter";

export interface DashboardSummary {
  total: number;
  needsAttention: number;
  attentionIds: string[];
  byTone: Record<string, number>;
}

const ATTENTION_TONES = new Set(["warn", "danger"]);

/** A row needs attention when any of its badges is in a warning or danger tone. */
export function summarize(rows: OrderRow[]): DashboardSummary {
  const byTone: Record<string, number> = {};
  const attentionIds: string[] = [];
  for (const row of rows) {
    byTone[row.status.tone] = (byTone[row.status.tone] ?? 0) + 1;
    const badges = [row.status, row.payment, row.shipment].filter((b): b is NonNullable<typeof b> => b !== null);
    if (badges.some((b) => ATTENTION_TONES.has(b.tone))) attentionIds.push(row.id);
  }
  return { total: rows.length, needsAttention: attentionIds.length, attentionIds, byTone };
}
import { orderTotal } from "../domain/order";
import { OrderAggregate } from "../service/orderQueryService";
import { Badge, badgeFor } from "../ui/badges";
import { formatWon } from "../util/money";

export interface OrderRow {
  id: string;
  customer: string;
  total: string;
  status: Badge;
  payment: Badge | null;
  shipment: Badge | null;
}

export function presentRow(agg: OrderAggregate, locale: string): OrderRow {
  return {
    id: agg.order.id,
    customer: agg.order.customer,
    total: formatWon(orderTotal(agg.order), locale),
    status: badgeFor(agg.order.status),
    payment: agg.payment ? badgeFor(agg.payment.status) : null,
    shipment: agg.shipment ? badgeFor(agg.shipment.status) : null,
  };
}
export enum OrderStatus {
  Pending = "PENDING",
  Confirmed = "CONFIRMED",
  Shipped = "SHIPPED",
  Completed = "COMPLETED",
  Cancelled = "CANCELLED",
}

export interface OrderLine {
  sku: string;
  qty: number;
  unitPrice: number; // minor units (e.g. won)
}

export interface Order {
  id: string;
  customer: string;
  status: OrderStatus;
  lines: OrderLine[];
  createdAt: number;
}

export function orderTotal(order: Order): number {
  return order.lines.reduce((sum, l) => sum + l.qty * l.unitPrice, 0);
}

const TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  [OrderStatus.Pending]: [OrderStatus.Confirmed, OrderStatus.Cancelled],
  [OrderStatus.Confirmed]: [OrderStatus.Shipped, OrderStatus.Cancelled],
  [OrderStatus.Shipped]: [OrderStatus.Completed],
  [OrderStatus.Completed]: [],
  [OrderStatus.Cancelled]: [],
};

export function canTransition(from: OrderStatus, to: OrderStatus): boolean {
  return TRANSITIONS[from].includes(to);
}

export function isOrderStatus(s: string): s is OrderStatus {
  return (Object.values(OrderStatus) as string[]).includes(s);
}
export enum PaymentStatus {
  Pending = "PENDING",
  Authorized = "AUTHORIZED",
  Captured = "CAPTURED",
  Failed = "FAILED",
  Refunded = "REFUNDED",
}

export interface Payment {
  orderId: string;
  status: PaymentStatus;
  amount: number;
  method: "card" | "transfer" | "points";
  updatedAt: number;
}

export function isPaymentStatus(s: string): s is PaymentStatus {
  return (Object.values(PaymentStatus) as string[]).includes(s);
}
export enum ShipmentStatus {
  Ready = "READY",
  InTransit = "IN_TRANSIT",
  Delivered = "DELIVERED",
  Failed = "FAILED",
  Returned = "RETURNED",
}

export interface Shipment {
  orderId: string;
  status: ShipmentStatus;
  carrier: string;
  trackingNo?: string;
  updatedAt: number;
}

export function isShipmentStatus(s: string): s is ShipmentStatus {
  return (Object.values(ShipmentStatus) as string[]).includes(s);
}
